  "intervention_target": "objective",
  "rationale": "Increase explicit encouragement of diverse, boundary, and varied-parameter designs so the search can escape the central local region. Analyzer recommends adding parameter_spread and increasing distance_from_center weight; these are low-risk objective edits expected to boost variance and exploration while keeping performance as primary objective.",
  "proposed_change": {
    "ops": [
      {
        "op": "set_weight",
        "name": "distance_from_center",
        "weight": 0.5
